import{_ as e,a as r,b as s,c as a,d as o,e as i,f as l,g as n,h as c,i as d,j as p,k as m,l as g,m as u,n as h,o as b}from"./chunks/pic15.Co_Gzw6B.js";import{_ as k,o as _,c as f,ab as w}from"./chunks/framework.D0eY5yx_.js";const T=JSON.parse('{"title":"راهنمای راه‌اندازی کد وورکر ZiZifn","description":"آموزش گام‌به‌گام فورک کردن پروژه، دریافت اطلاعات کلودفلر و دپلوی خودکار وورکر با گیت‌هاب اکشنز و در نهایت ساخت کانفیگ پروکسی VLESS","frontmatter":{"layout":"doc","outline":"deep","lang":"fa-IR","dir":"rtl","title":"راهنمای راه‌اندازی کد وورکر ZiZifn","description":"آموزش گام‌به‌گام فورک کردن پروژه، دریافت اطلاعات کلودفلر و دپلوی خودکار وورکر با گیت‌هاب اکشنز و در نهایت ساخت کانفیگ پروکسی VLESS","date":"2026-07-04T00:00:00.000Z","editLink":true,"head":[["meta",{"name":"description","content":"آموزش کامل دپلوی پروکسی VLESS بر پایه وب‌اسمبلی و راست روی ورکر کلودفلر با استفاده از گیت‌هاب اکشنز"}],["meta",{"name":"keywords","content":"serverless runtime, cloudflare worker, vless proxy, github actions, rust wasm, zizifn, wrangler deploy"}]]},"headers":[],"relativePath":"en/topics/zizifn.md","filePath":"en/topics/zizifn.md"}'),y={name:"en/topics/zizifn.md"};function S(x,t,v,P,V,A){return _(),f("div",null,[...t[0]||(t[0]=[w('<h2 id="راهنمای-جامع-راه‌اندازی-و-دپلوی-خودکار-پروکسی-vless" tabindex="-1">راهنمای جامع راه‌اندازی و دپلوی خودکار پروکسی VLESS <a class="header-anchor" href="#راهنمای-جامع-راه‌اندازی-و-دپلوی-خودکار-پروکسی-vless" aria-label="Permalink to &quot;راهنمای جامع راه‌اندازی و دپلوی خودکار پروکسی VLESS&quot;">​</a></h2><p><strong>آموزش گام‌به‌گام فورک کردن، پیکربندی سکرت‌های امنیتی و اجرای دستی گیت‌هاب اکشن</strong></p><br><p align="center"><img src="'+e+'" alt="VLESS Worker Deployment" width="1080px"></p><p><br><br></p><div class="tip custom-block"><p class="custom-block-title">اجرای بدون دردسر</p><p>در این ساختار جدید، هیچ نیازی به دستکاری فایل‌های پروژه، اضافه یا حذف کردن کدهای مخزن یا ارسال کامیت‌های الکی ندارید! همه‌چیز با تنظیم متغیرها و یک کلیک ساده دپلوی می‌شود. 😎</p></div><p>پروژه <strong>zizifn</strong> یک کانفیگ پروکسی امن بر پایه پروتکل VLESS-WS-TLS است که با زبان Rust و معماری وب‌اسمبلی (Wasm) توسعه یافته و به کمک ابزار Wrangler روی ورکر کلودفلر اجرا می‌شود. برای اینکه بتوانید این پروژه را روی اکانت شخصی خود پیاده‌سازی کنید، مراحل زیر را گام‌به‌گام دنبال کنید.</p><hr><br><h2 id="گام-اول-فورک-کردن-ریپازیتوری-fork" tabindex="-1">گام اول: فورک کردن ریپازیتوری (Fork) <a class="header-anchor" href="#گام-اول-فورک-کردن-ریپازیتوری-fork" aria-label="Permalink to &quot;گام اول: فورک کردن ریپازیتوری (Fork)&quot;">​</a></h2><p>در قدم اول باید یک نسخه از این پروژه را روی حساب گیت‌هاب خود کپی کنید.</p><p>۱. به صفحه اصلی ریپازیتوری پروژه بروید، <a href="https://github.com/NiREvil/zizifn" target="_blank" rel="noreferrer">لیــنک</a> ۲. از بالای صفحه بر روی آیکون <strong>Fork</strong> (فلش قرمز) کلیک کنید.</p><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+r+'" alt="نحوه فورک کردن پروژه در گیت‌هاب" width="1080px"></p></details><br><p>۳. در صفحه بعد می‌توانید اسم دلخواه برای فورک تعیین کنید در غیر این‌صورت بر روی گزینه‌ی <strong>Create fork</strong> کلیک کنید تا پروژه به حساب شما منتقل شود.</p><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+s+'" alt="نحوه فورک کردن پروژه در گیت‌هاب" width="1080px"></p></details><br><hr><h2 id="گام-دوم-دریافت-اطلاعات-لازم-از-کلودفلر" tabindex="-1">گام دوم: دریافت اطلاعات لازم از کلودفلر <a class="header-anchor" href="#گام-دوم-دریافت-اطلاعات-لازم-از-کلودفلر" aria-label="Permalink to &quot;گام دوم: دریافت اطلاعات لازم از کلودفلر&quot;">​</a></h2><p>برای دپلوی خودکار، گیت‌هاب اکشنز نیاز دارد به حساب کلودفلر شما متصل شود. برای این کار به دو فاکتور اساسی نیاز داریم:</p><ul><li>CloudFlare Account ID</li><li>CloudFlare API Token</li></ul><div class="info custom-block"><p class="custom-block-title"><strong>نکته</strong></p><p>قبلا برای دریافت اکانت آی‌دی باید وارد صفحه وورکر و پیج‌ها می‌شدیم و از پایین صفحه اکانت آی‌دی رو کپی می‌کردیم ولی حالا موقع ساختن توکن، خودش ای‌دی هم نمایش میده پس همونجا کپی می‌کنیم.</p></div><h3 id="ساخت-api-token-با-دسترسی-ویرایش-ورکر" tabindex="-1">ساخت API Token با دسترسی ویرایش ورکر <a class="header-anchor" href="#ساخت-api-token-با-دسترسی-ویرایش-ورکر" aria-label="Permalink to &quot;ساخت API Token با دسترسی ویرایش ورکر&quot;">​</a></h3><p>۱. بعد از <a href="https://dash.cloudflare.com/login" target="_blank" rel="noreferrer">ورود</a> و یا <a href="https://dash.cloudflare.com/sign-up" target="_blank" rel="noreferrer">ساخت اکانت</a> در کلودفلر، از بالای صفحه منوی سمت چپ را باز کرده و در کادر <strong>Quick search</strong> عبارت <strong>api</strong> را تایپ کرده و سپس از بین نتایج جستجو <strong>Account API Tokens</strong> را انتخاب کنید.</p><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+a+'" alt="جستجوی توکن api" width="1080px"></p><br><p align="center"><img src="'+o+'" alt="انتخاب account api tokens" width="1080px"></p></details><p>۲. روی دکمه <strong>Create Token</strong> کلیک کنید.</p><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+i+'" alt="کلیک روی Create token" width="1080px"></p></details><p>۳. از بین قالب‌های آماده (فلش قرمز رنگ) بر روی گزینه <strong>Edit Cloudflare Workers</strong> را انتخاب کنید.</p><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+l+'" alt="تغییر قالب توکن" width="1080px"></p><br><p align="center"><img src="'+n+'" alt="انتخاب قالب ادیت وورکر" width="1080px"></p></details><p>۴. در بخش <strong>Token Expiration</strong> بر حسب نیاز یک باز‌ی زمانی برای منقضی شدن توکن خود مشخص کرده سپس بر روی گزینه مشاهده و ایجاد توکن کلید کنید.</p><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+c+'" alt="زمان اکسپایر شدن توکن" width="1080px"></p></details><div class="danger custom-block"><p class="custom-block-title"><strong>نکته</strong></p><p>توجه داشته باشید که پس از منقضی شدن توکن، وورکر شما از کار نخواهد افتاد، از آن پس قادر به دپلوی کردن مجدد پروژه از طریق گیت‌هاب نخواهید بود، که در این‌صورت باید مجددا توکن جدید ساخته و جایگزین توکن قبلی در تنظیمات ریپو گیت‌هاب خود کنید.</p></div><p>۵. در این صفحه توکن ساخته‌شده را کپی کنید (این توکن فقط یک‌بار نمایش داده می‌شود پس در صورت نیاز آن‌را در جایی ذخیره کنید). همچنین در ابتدای این صفحه Account ID نیز نمایش داده میشود، آنرا نیز کپی کنید چون بهش نیاز داریم. پس از اطمینان از کپی شدن هردو؛ بر روی گزینه <strong>confirm</strong> جهت بسته شدن پنجره فعال کلید کنید.</p><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+d+'" alt="کپی آی‌دی و توکن کلودفلر" width="1080px"></p></details><br><hr><h2 id="گام-سوم-تنظیم-سکرت‌ها-در-گیت‌هاب-github-secrets" tabindex="-1">گام سوم: تنظیم سکرت‌ها در گیت‌هاب (GitHub Secrets) <a class="header-anchor" href="#گام-سوم-تنظیم-سکرت‌ها-در-گیت‌هاب-github-secrets" aria-label="Permalink to &quot;گام سوم: تنظیم سکرت‌ها در گیت‌هاب (GitHub Secrets)&quot;">​</a></h2><p>حالا باید اطلاعات دریافتی را به ریپازیتوری فورک‌شده‌ی خود در گیت‌هاب معرفی کنید تا اکشن بتواند با حساب کلودفلر شما احراز هویت کند.</p><p>۱. در ریپازیتوری فورک‌شده خود، به تب <strong>Settings</strong> بروید.</p><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+p+'" alt="ورود به تنظیمات رپو" width="1080px"></p></details><br><p>۲. از داخل منو بر روی گزینه <strong>Secrets and variables</strong> کلیک کرده و از منوی زیرمجموعه آن یعنی <strong>Actions</strong> را انتخاب کنید.</p><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+m+'" alt="انتخاب Actions" width="1080px"></p></details><br><p>۳. روی دکمه <strong>New repository secret</strong> کلیک کنید و متغیرها را بر اساس جدول زیر تعریف کنید:</p><br><table tabindex="0"><thead><tr><th>نام سکرت (Secret Name)</th><th style="text-align:center;">وضعیت</th><th>مقدار پیش‌فرض</th><th>توضیحات</th></tr></thead><tbody><tr><td><code>CLOUDFLARE_API_TOKEN</code></td><td style="text-align:center;">✔️ اجباری</td><td>-</td><td>توکن کلودفلر شما که اجازه ویرایش ورکرها را دارد.</td></tr><tr><td><code>CLOUDFLARE_ACCOUNT_ID</code></td><td style="text-align:center;">✔️ اجباری</td><td>-</td><td>آی‌دی حساب کلودفلر شما.</td></tr><tr><td><code>UUID</code></td><td style="text-align:center;">⚙️ اختیاری</td><td><code>be0ff9df-1468-41a0-8865-796d1c6800db</code></td><td>یوآی‌دی اختصاصی شما (ورژن ۴).</td></tr><tr><td><code>PROXYIP</code></td><td style="text-align:center;">⚙️ اختیاری</td><td><code>di.nscl.ir</code></td><td>آی‌پی یا دامین تمیز کلودفلر جهت مسیریابی ترافیک پشت پروکسی.</td></tr></tbody></table><br><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+g+'" alt="ایجاد سکرت۱" width="1080px"></p><br><p align="center"><img src="'+u+'" alt="ایجاد سکرت۲" width="1080px"></p><br><p align="center"><img src="'+h+'" alt="ایجاد سکرت نهایی" width="1080px"></p><br></details><br><div class="danger custom-block"><p class="custom-block-title"><strong>نکته مهم</strong></p><p>هردو متغیر اول (آیدی و توکن کلودفلر) اجباری هستند یعنی بدون دریافت این دو و قرار دادنشان در سکرت گیت‌هاب امکان دپلوی کردن وورکر وجود نخواهد داشت، ولی دو متغیر بعدی یعنی UUID و PROXYIP اختیاری هستند چون برای هردو یک مقدار پیشفرض داخل کد تعیین شده، ولی به شدت توصیه میشود که برای خود از داخل <a href="https://www.uuidgenerator.net" target="_blank" rel="noreferrer">این سایــت</a> یک آی‌دی کپی کرده و از آن استفاده کنید‌.</p><hr><h2 id="گام-چهارم-فعال‌سازی-و-اجرای-دستی-اکشن-manual-deploy" tabindex="-1">گام چهارم: فعال‌سازی و اجرای دستی اکشن (Manual Deploy) <a class="header-anchor" href="#گام-چهارم-فعال‌سازی-و-اجرای-دستی-اکشن-manual-deploy" aria-label="Permalink to &quot;گام چهارم: فعال‌سازی و اجرای دستی اکشن (Manual Deploy)&quot;">​</a></h2><p>گیت‌هاب به طور پیش‌فرض اجرای اکشن‌ها را روی ریپازیتوری‌های فورک‌شده متوقف می‌کند. باید یک‌بار آن را فعال و سپس اجرا کنیم.</p><p>۱. به تب <strong>Actions</strong> در بالای ریپازیتوری خود بروید. ۲. روی دکمه سبز رنگ <strong>&quot;I understand my workflows, go ahead and enable them&quot;</strong> کلیک کنید تا اکشن‌ها مجاز به فعالیت شوند. ۳. از منوی سمت چپ، جریان کاری یا همان ورک‌فلوِ <strong>Deploy Worker</strong> را انتخاب کنید. ۴. در سمت راست صفحه، یک نوار باریک با دکمه‌ی <strong>Run workflow</strong> ظاهر می‌شود. روی آن کلیک کنید. ۵. در فرم پاپ‌آپی که باز می‌شود، می‌توانید به صورت اختیاری مقادیر <code>Proxy IP</code> یا <code>UUID</code> جدیدی را برای این اجرای خاص تایپ کنید (اگر خالی بگذارید از سکرت‌ها یا پیش‌فرض‌های سیستم استفاده می‌شود). ۶. در نهایت دکمه‌ی سبز رنگ <strong>Run workflow</strong> را در آن فرم کوچک بفشارید.</p><br><p align="center"><img src="'+b+'" alt="نحوه فعال‌سازی و اجرای دستی گیت‌هاب اکشنز" width="1080px"></p><br><p>::: note یادداشت مهم برای متغیرهای یک‌بار مصرف</p><p>مقادیری که در فرم پاپ‌آپ دکمه‌ی <strong>Run workflow</strong> وارد می‌کنید، کاملاً یک‌بار مصرف هستند و در تنظیمات ریپازیتوری ذخیره نمی‌شوند. این قابلیت برای تست سریع آی‌پی‌های تمیز مختلف فوق‌العاده کاربردی است.</p></div><p>پس از کلیک روی دکمه، گیت‌هاب سرور ابری را روشن کرده، کامپایلر زبان راست (<code>cargo</code>) و ابزار <code>wasm-pack</code> را راه‌اندازی می‌کند، کدها را کامپایل کرده و به طور اتوماتیک یک Worker جدید به نام <code>zr-wasm</code> در حساب کلودفلر شما ساخته و کدهایتان را روی آن منتشر می‌کند!</p><br><div class="info custom-block"><p class="custom-block-title">راهنما و کپی‌رایت</p><p>مستندات آماده‌سازی شده برای پنل VitePress پروژه زیزفن.</p><div dir="ltr"><p><strong>Deployment Engine</strong></p><ul><li>GitHub Actions workflow runner (Ubuntu-24.04 VM)</li><li>Cloudflare Wrangler Action v3</li></ul></div></div><br><div class="danger custom-block"><p class="custom-block-title">هشدار امنیتی</p><details class="details custom-block"><summary>برای مشاهده نکات مهم امنیتی کلیک کنید</summary><div dir="rtl"><p><strong>هرگز توکن‌های حساس کلودفلر را در فیلدهای متنی ورودی دستی تعریف نکنید!</strong></p><p>مقادیری که در فرم دستی وارد می‌کنید در تاریخچه لاگ‌های گیت‌هاب ذخیره شده و اگر ریپازیتوری شما عمومی (Public) باشد برای همگان قابل رویت خواهد بود. سکرت‌های حساس کلودفلر حتماً و باید از طریق مسیر ذکر شده در <strong>گام سوم</strong> (بخش Repository Secrets) ثبت شوند تا گیت‌هاب آن‌ها را رمزنگاری (Encrypt) کند.</p></div></details></div>',56)])])}const z=k(y,[["render",S]]);export{T as __pageData,z as default};
